func (s *FakeRemoteSite) GetName() string {
	return s.Name
}

// Dial returns the connection to the remote site.
func (s *FakeRemoteSite) Dial(params DialParams) (net.Conn, error) {
	readerConn, writerConn := net.Pipe()
	s.ConnCh <- readerConn
	return writerConn, nil
